```mswea_bash_command
python3 - <<'PY'
p='/app/server.py';s=open(p).read()
s=s.replace('<form id="workspace-create-form" data-testid="workspace-create-form"></form>','<form id="workspace-create-form" data-testid="workspace-create-form"><input name="name"><input name="slug"><button type="submit">Create workspace</button></form>')
s=s.replace('<form id="create-channel-form" data-testid="create-channel-form"><input id="create-channel-private"', '<form id="create-channel-form" data-testid="create-channel-form"><input name="name"><input id="create-channel-private"')
a=s.index('<script>const f=document.querySelector')
b=s.index('</script>',a)
js=r'''<script>
const $=s=>document.querySelector(s), tid=s=>`[data-testid="${s}"]`;
let token=localStorage.getItem("huddle.token"), current=null, channels=[];
function showAuth(){ $(tid("auth-form")).style.display=""; $("auth-modal").style.display=""; }
function hideAuth(){ $(tid("auth-form")).style.display="none"; $("auth-modal").style.display="none"; }
function api(path,opt={}){opt.headers=Object.assign({"Content-Type":"application/json","Authorization":"Bearer "+token},opt.headers||{});return fetch(path,opt).then(async r=>({r,x:await r.json().catch(()=>({}))}));}
function renderChannels(){let box=$(tid("channel-list"));box.innerHTML="";channels.forEach(c=>{let e=document.createElement("div");e.dataset.testid="channel-entry";e.dataset.channelId=c.id;e.dataset.channelName=c.name;e.textContent="#"+c.name;e.onclick=()=>selectChannel(c);box.append(e)});}
async function selectChannel(c){current=c;$("channel-title").textContent="# "+c.name;$("channel-topic").textContent=c.topic||"";let z=await api("/api/channels/"+c.id+"/messages");$(tid("message-list")).innerHTML="";if(!z.x.messages.length)$(tid("channel-empty-state")).style.display="block";else $(tid("channel-empty-state")).style.display="none";}
async function loadWorkspace(w){let z=await api("/api/workspaces/"+w.slug);$("workspace-header").textContent=w.name;channels=z.x.channels||[];renderChannels();if(channels[0])selectChannel(channels[0]);}
async function loginOrSignup(e){e.preventDefault();let b=Object.fromEntries(new FormData(e.target));let q=await fetch("/api/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(b)});if(q.status==401)q=await fetch("/api/auth/register",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(b)});let x=await q.json();if(!q.ok){$(tid("auth-error")).textContent=x.error||"Invalid credentials";$(tid("auth-error")).style.display="block";return}token=x.token;localStorage.setItem("huddle.token",token);$(tid("current-user")).textContent=x.user.display_name||x.user.username;hideAuth();let w=await api("/api/workspaces");if(w.x.workspaces&&w.x.workspaces[0])loadWorkspace(w.x.workspaces[0]);}
$(tid("auth-form")).onsubmit=loginOrSignup;
$(tid("logout-btn")).onclick=()=>{localStorage.removeItem("huddle.token");token=null;showAuth();};
$(tid("workspace-create-form")).onsubmit=async e=>{e.preventDefault();let b=Object.fromEntries(new FormData(e.target)),z=await api("/api/workspaces",{method:"POST",body:JSON.stringify(b)});if(z.r.ok)loadWorkspace(z.x.workspace);};
$(tid("new-channel-btn")).onclick=()=>$(tid("create-channel-form")).style.display="block";
$(tid("create-channel-form")).onsubmit=async e=>{e.preventDefault();let b=Object.fromEntries(new FormData(e.target));if(!current)return;let z=await api("/api/workspaces/"+(await api("/api/workspaces")).x.workspaces[0].slug+"/channels",{method:"POST",body:JSON.stringify(b)});if(!z.r.ok){$(tid("create-channel-error")).textContent="Channel already exists";$(tid("create-channel-error")).style.display="block";return}channels.push(z.x.channel);renderChannels();selectChannel(z.x.channel);};
if(token){hideAuth();api("/api/auth/me").then(z=>{$(tid("current-user")).textContent=z.x.user.display_name||z.x.user.username;return api("/api/workspaces")}).then(z=>{if(z.x.workspaces&&z.x.workspaces[0])loadWorkspace(z.x.workspaces[0])});}
</script>'''
open(p,'w').write(s[:a]+js+s[b+9:])
